import os
import queue
import threading
from typing import Callable, Iterable, Optional

import azure.cognitiveservices.speech as speechsdk


class StreamingSpeechToText:
    def __init__(
        self,
        language: str = "en-US",
        enable_punctuation: bool = True,
        sample_rate: int = 16000,
        channels: int = 1,
        on_partial: Optional[Callable[[str], None]] = None,
        on_final: Optional[Callable[[str], None]] = None,
    ):
        self.language = language
        self.enable_punctuation = enable_punctuation
        self.sample_rate = sample_rate
        self.channels = channels
        self.on_partial = on_partial
        self.on_final = on_final

        key = os.environ.get("AZURE_SPEECH_KEY")
        region = os.environ.get("AZURE_SPEECH_REGION")
        if not key or not region:
            raise ValueError("AZURE_SPEECH_KEY and AZURE_SPEECH_REGION must be set")

        self.speech_config = speechsdk.SpeechConfig(subscription=key, region=region)
        self.speech_config.speech_recognition_language = self.language
        self.speech_config.output_format = speechsdk.OutputFormat.Detailed

        # Azure Speech uses dictation mode for punctuation in continuous recognition
        self.speech_config.set_property(
            speechsdk.PropertyId.SpeechServiceConnection_EnableDictation,
            "true" if self.enable_punctuation else "false",
        )

        self._push_stream = speechsdk.audio.PushAudioInputStream()
        audio_format = speechsdk.audio.AudioStreamFormat(
            samples_per_second=self.sample_rate,
            bits_per_sample=16,
            channels=self.channels,
        )
        audio_config = speechsdk.audio.AudioConfig(stream=self._push_stream, format=audio_format)
        self.recognizer = speechsdk.SpeechRecognizer(
            speech_config=self.speech_config,
            audio_config=audio_config,
        )

        self._events_started = False
        self._done = threading.Event()
        self._results = queue.Queue()

    def _wire_events(self) -> None:
        if self._events_started:
            return

        def recognized(evt: speechsdk.SpeechRecognitionEventArgs):
            text = evt.result.text.strip()
            if text:
                if self.on_final:
                    self.on_final(text)
                self._results.put(("final", text))

        def recognizing(evt: speechsdk.SpeechRecognitionEventArgs):
            text = evt.result.text.strip()
            if text:
                if self.on_partial:
                    self.on_partial(text)
                self._results.put(("partial", text))

        def canceled(evt):
            self._results.put(("canceled", getattr(evt, "reason", "unknown")))
            self._done.set()

        def session_stopped(evt):
            self._results.put(("stopped", None))
            self._done.set()

        self.recognizer.recognizing.connect(recognizing)
        self.recognizer.recognized.connect(recognized)
        self.recognizer.canceled.connect(canceled)
        self.recognizer.session_stopped.connect(session_stopped)
        self._events_started = True

    def start(self) -> None:
        self._wire_events()
        self.recognizer.start_continuous_recognition()

    def stop(self) -> None:
        self.recognizer.stop_continuous_recognition()
        self._done.set()

    def feed(self, audio_chunk: bytes) -> None:
        if not isinstance(audio_chunk, (bytes, bytearray)):
            raise TypeError("audio_chunk must be bytes-like PCM16 audio")
        self._push_stream.write(audio_chunk)

    def end(self) -> None:
        self._push_stream.close()
        self.stop()

    def iter_results(self, timeout: Optional[float] = None):
        while not self._done.is_set() or not self._results.empty():
            try:
                yield self._results.get(timeout=timeout)
            except queue.Empty:
                if self._done.is_set():
                    break

    def recognize_audio_chunks(self, audio_chunks: Iterable[bytes]):
        self.start()
        try:
            for chunk in audio_chunks:
                self.feed(chunk)
        finally:
            self.end()
        return list(self.iter_results(timeout=0.1))
